class WeatherCache {
  constructor(maxSize = 3) {
    this.maxSize = maxSize;
  }

  get(city) {
    const cache = JSON.parse(localStorage.getItem('weather_cache')) || {};
    return cache[city] || null;
  }

  set(city, data) {
    const cache = JSON.parse(localStorage.getItem('weather_cache')) || {};
    const keys = Object.keys(cache);

    if (!cache[city] && keys.length >= this.maxSize) {
      const oldestKey = keys.reduce((oldest, key) =>
        cache[key].timestamp < cache[oldest].timestamp ? key : oldest
      );
      delete cache[oldestKey];
    }

    cache[city] = {
      ...data,
      timestamp: Date.now()
    };

    localStorage.setItem('weather_cache', JSON.stringify(cache));
  }
}

async function fetchWithCache(city) {
  const cache = new WeatherCache();
  const cachedData = cache.get(city);

  if (cachedData) {
    return cachedData;
  }

  const response = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=${process.env.OPENWEATHER_API_KEY}`);
  const data = await response.json();

  cache.set(city, data);
  return data;
}
